{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In healthy volunteers, oral chrysin bioavailability was estimated at less than 1%, a direct human measurement far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The predicted absolute oral bioavailability of chrysin in humans was 0.003–0.02%, strongly supporting low F for a related polyphenolic natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Peonidin glycosides in humans showed systemic availability of only 0.24–0.48%, demonstrating very low oral bioavailability for polyphenolic glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Flavonolignans in patients had very low oral bioavailability inferred from high apparent oral clearances (151–2016 L/h), supporting low F for polyphenolic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Curcumin consistently shows low/poor oral bioavailability in humans due to poor solubility, chemical instability, and rapid metabolism, supporting low F for the query's polyphenolic class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable experimental evidence from related polyphenolic natural products—flavones, flavonolignans, anthocyanins, and curcumin—shows very low oral bioavailability (<1% to a few percent), supporting a low F (<20%) prediction for the query coumarin.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for scopoletin itself; extrapolation relies on related polyphenolic natural products.",
    "The query is a small coumarin, whereas most evidence comes from larger, more polar flavonoids/anthocyanins, so the magnitude of low F may differ.",
    "Human absolute bioavailability data for the exact query compound are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

